	@Test
	void uniformSpilledRelationsKeepScanAndEmptyCandidatePaths() throws Exception {
		for (boolean bound : new boolean[] { false, true }) {
			try (Fixture fixture = new Fixture("4096")) {
				long match = fixture.term(SimpleValueFactory.getInstance().createIRI("urn:match"));
				long miss = fixture.term(SimpleValueFactory.getInstance().createIRI("urn:miss"));
				String label = "payload".repeat(1024);
				long payload = fixture.term(SimpleValueFactory.getInstance().createLiteral(label));
				ValuesRow[] rows = new ValuesRow[3];
				for (int i = 0; i < rows.length; i++) {
					rows[i] = bound
							? new ValuesRow(new int[] { KEY, PAYLOAD }, new long[] { match, payload })
							: new ValuesRow(new int[] { PAYLOAD }, new long[] { payload });
				}
				try (OptionalCompatibilityIndex index = fixture.build(rows)) {
					assertThat(index.spilled()).isTrue();
					assertThat(collect(index, fixture, match)).containsExactly(label, label, label);
					long decoded = index.metrics().decodedRows();
					assertThat(collect(index, fixture, miss)).hasSize(bound ? 0 : rows.length);
					assertThat(index.metrics().decodedRows()).isEqualTo(decoded + (bound ? 0L : rows.length));
					assertNoPostingProbe(index);
				}
			}
		}
	}

	@Test
	void mixedRelationIndexesOnlyItsSelectiveSharedColumn() throws Exception {
		try (Fixture fixture = new Fixture("4096")) {
			long key = fixture.term(SimpleValueFactory.getInstance().createIRI("urn:constant"));
			ValuesRow[] rows = new ValuesRow[96];
			long selected = 0L;
			for (int i = 0; i < rows.length; i++) {
				selected = fixture.term(SimpleValueFactory.getInstance().createLiteral("row-" + i));
				rows[i] = new ValuesRow(new int[] { KEY, PAYLOAD }, new long[] { key, selected });
			}
			int probes = 8;
			RowState sample = fixture.row.fork();
			sample.replaceSlot(KEY, key);
			sample.replaceSlot(PAYLOAD, selected);
			OptionalExecutionStrategy.ProbeDemand demand = OptionalExecutionStrategy.ProbeDemand.exact(
					new RowState[] { sample }, new long[] { probes }, false, 0L,
					"proven-repeated-exact-probe-key");
			try {
				try (OptionalCompatibilityIndex index = fixture.build(rows, new int[] { KEY, PAYLOAD },
						OptionalCompatibilityIndex.Strategy.AUTO, demand)) {
					fixture.row.replaceSlot(KEY, key);
					fixture.row.replaceSlot(PAYLOAD, selected);
					for (int attempt = 0; attempt < probes; attempt++) {
						try (var probe = index.probe(fixture.row)) {
							assertThat(probe.next()).isTrue();
							assertThat(probe.current().cell(PAYLOAD).value().stringValue()).isEqualTo("row-95");
							assertThat(probe.next()).isFalse();
						}
					}
					assertThat(index.metrics().constructedPostings()).isEqualTo(rows.length);
					assertThat(index.metrics().rangeSearches()).isEqualTo(4L * probes);
					assertThat(index.metrics().candidateRows()).isEqualTo(probes);
				}
			} finally {
				sample.closeDecodedInputs();
			}
		}
	}

