	private static List<String> collect(OptionalCompatibilityIndex index, Fixture fixture, long key)
			throws IOException {
		fixture.row.replaceSlot(KEY, key);
		Value expectedKey = fixture.values.get(key);
		List<String> result = new ArrayList<>();
		try (OptionalCompatibilityIndex.Probe probe = index.probe(fixture.row)) {
			while (probe.next()) {
				NativeResultCell candidateKey = probe.sharedCell(0);
				if (candidateKey.state() != NativeResultCell.State.BOUND
						|| candidateKey.value().equals(expectedKey)) {
					result.add(probe.current().cell(PAYLOAD).value().stringValue());
				}
			}
		}
		return result;
	}

	private static void assertNoPostingProbe(OptionalCompatibilityIndex index) {
		assertThat(index.metrics().rangeSearches()).as("scan strategy performs no posting range search").isZero();
		assertThat(index.metrics().postingReads()).as("scan strategy performs no posting read").isZero();
		assertThat(index.metrics().constructedPostings()).as("scan strategy constructs no postings").isZero();
	}

